<?php
declare(strict_types=1);
/* Halaman login dan registrasi warga. Video latar, kartu kaca, dan panel akun demo (tanpa menampilkan kata sandi). */
if (current_user()) redirect(url('beranda'));
$mode = in_array(gv('mode'), ['register'], true) ? 'register' : 'login'; $err = ''; $uval = '';
if (is_post()) {
    csrf_check(); $demo = (string) pv('demo', '');
    if ($demo !== '' && cfg('demo_mode', false) && isset(DEMO_PW[$demo])) { [$ok, $err] = do_login($demo, DEMO_PW[$demo], false); if ($ok) { flash('Selamat datang. Anda masuk dengan akun demo.'); redirect(url('beranda')); } }
    elseif ($mode === 'register') { [$ok, $err] = do_register((string) pv('nama'), (string) pv('username'), (string) pv('pw'), (string) pv('pw2')); $uval = (string) pv('username'); if ($ok) { flash('Akun dibuat. Selamat datang.'); redirect(url('beranda')); } }
    else { $uval = (string) pv('username'); [$ok, $err] = do_login($uval, (string) pv('pw'), (bool) pv('ingat')); if ($ok) redirect(url('beranda')); }
}
echo html_head('Masuk | SEA WARNING Pulo Panjang'), '<body>';
$q = '?v=' . (int) @filemtime(APP_ROOT . '/assets/media/login_loop.mp4');   // nama berkas yang sama tidak lagi memakai salinan lama dari cache peramban
echo '<div class="auth"><div class="vid" style="--poster:url(assets/media/poster.jpg' . $q . ')" aria-hidden="true"><video autoplay muted loop playsinline preload="auto" poster="assets/media/poster.jpg' . $q . '" class="on"><source src="assets/media/login_loop.webm' . $q . '" type="video/webm"><source src="assets/media/login_loop.mp4' . $q . '" type="video/mp4"></video></div>';
echo '<section class="auth-art" aria-label="Pengantar"><div class="brand wordmark"><img class="logo" src="assets/media/logo.png" alt="" width="58" height="51"><div><b>SEA WARNING</b><span>Pulo Panjang</span></div></div><div class="art-text"><h1>Sistem Peringatan Dini Banjir Rob Pulo Panjang</h1><p>Informasi zona kerawanan banjir rob yang mudah diakses dan dipahami, dari integrasi data topografi, oseanografi, dan ekologi perairan.</p></div>';
echo '<div class="art-kosong" aria-hidden="true"></div><p class="art-note">' . e(DISCLAIMER) . '</p></section>';
echo '<section class="auth-form"><div class="theme-corner rel"><button type="button" class="icon-btn snd-btn" id="snd" aria-pressed="false" aria-label="Nyalakan suara" title="Nyalakan suara">' . ic('volumeoff', 20, 'snd-off') . ic('volume', 20, 'snd-on') . '</button>' . skin_menu() . '</div><div class="auth-card">';
if ($mode === 'register') {
    echo '<h2>Buat akun warga</h2><p>Akun baru otomatis berperan Warga. Peran lain dibuat oleh administrator.</p>' . google_tombol('Daftar dengan Google') . '<div class="atau"><span>atau isi formulir</span></div><form method="post" action="' . e(url('login', ['mode' => 'register'])) . '" novalidate>' . csrf_field();
    echo '<div class="field"><label for="r-nama">Nama lengkap</label><input class="input" id="r-nama" name="nama" maxlength="100" value="' . e(pv('nama', '')) . '" required autocomplete="name"></div><div class="field"><label for="r-user">Nama pengguna</label><input class="input" id="r-user" name="username" maxlength="50" value="' . e($uval) . '" required autocomplete="username"><div class="hint">Minimal 3 karakter: huruf, angka, titik, garis bawah, atau strip.</div></div><div class="field"><label for="r-pw">Kata sandi</label><input class="input" id="r-pw" name="pw" type="password" autocomplete="new-password" required><div class="hint">Minimal 6 karakter.</div></div><div class="field"><label for="r-pw2">Ulangi kata sandi</label><input class="input" id="r-pw2" name="pw2" type="password" autocomplete="new-password" required></div>';
    echo ($err ? '<div class="err" role="alert" style="margin-bottom:12px">' . e($err) . '</div>' : '') . '<button class="btn btn-primary btn-block" style="height:46px" type="submit">Buat akun dan masuk</button></form><div class="auth-links">Sudah punya akun? <a href="' . e(url('login')) . '">Masuk</a></div>';
} else {
    echo '<h2>Masuk</h2><p>Masuk untuk melihat status banjir rob, peta zona kerawanan, dan informasi kesiapsiagaan.</p>';
    foreach (flashes() as [$t, $m]) echo '<div class="note" style="margin-bottom:14px">' . ic('info', 18) . '<div>' . e($m) . '</div></div>';
    echo '<form method="post" action="' . e(url('login')) . '" novalidate>' . csrf_field() . '<div class="field"><label for="l-user">Nama pengguna</label><input class="input" id="l-user" name="username" value="' . e($uval) . '" autocomplete="username" autocapitalize="none" spellcheck="false" required autofocus></div><div class="field"><label for="l-pw">Kata sandi</label><input class="input" id="l-pw" name="pw" type="password" autocomplete="current-password" required></div><label class="chk" style="margin-bottom:16px"><input type="checkbox" name="ingat" value="1"><span>Ingat saya selama 30 hari</span></label>' . ($err ? '<div class="err" role="alert" style="margin-bottom:12px">' . e($err) . '</div>' : '') . '<button class="btn btn-primary btn-block" style="height:46px" type="submit">Masuk</button></form><div class="atau"><span>atau</span></div>' . google_tombol('Masuk dengan Google') . '<div class="auth-links">Warga baru? <a href="' . e(url('login', ['mode' => 'register'])) . '">Buat akun warga</a></div>';
    if (cfg('demo_mode', false)) { echo '<form class="demo" method="post" action="' . e(url('login')) . '">' . csrf_field() . '<div class="demo-h"><span>Coba langsung sebagai</span></div><div class="roles">'; foreach ([['admin', 'Administrator', 'admin'], ['mahasiswa', 'Mahasiswa', 'mahasiswa'], ['perangkat', 'Perangkat Desa', 'perangkat_desa'], ['warga', 'Warga', 'warga']] as [$u, $lb, $r]) echo '<button type="submit" name="demo" value="' . $u . '" aria-label="Masuk sebagai ' . e(roles()[$r]['label']) . ' (akun demo)">' . ic(roles()[$r]['icon'], 20) . '<span>' . e($lb) . '</span></button>'; echo '</div><p class="demo-n">Akun demo untuk pengembangan. Hapus sebelum dipakai sungguhan.</p></form>'; }
    echo '<p class="auth-disc">' . e(DISCLAIMER) . '</p>';
}
echo '</div></section></div>', toasts(), '<script>(function(){var b=document.getElementById("snd"),v=document.querySelector(".vid video");if(!b||!v)return;var K="sw_suara",mau=true,ev=["pointerdown","keydown","touchstart"];try{mau=localStorage.getItem(K)!=="mati"}catch(e){}function ui(){var on=!v.muted;b.setAttribute("aria-pressed",on);b.title=on?"Matikan suara":"Nyalakan suara";b.setAttribute("aria-label",b.title);b.classList.toggle("on",on);b.classList.toggle("tunggu",mau&&!on)}function simpan(x){try{localStorage.setItem(K,x?"nyala":"mati")}catch(e){}}function lepas(){ev.forEach(function(n){document.removeEventListener(n,gerak,true)})}function nyala(){v.muted=false;v.volume=.85;var p=v.play();ui();return p&&p.then?p:Promise.resolve()}function gerak(e){if(e.target&&e.target.closest&&e.target.closest("#snd"))return;lepas();if(mau&&v.muted)nyala().catch(function(){v.muted=true;ui()})}function tunggu(){ev.forEach(function(n){document.addEventListener(n,gerak,true)})}b.addEventListener("click",function(){lepas();if(v.muted){mau=true;simpan(true);nyala().catch(function(){v.muted=true;ui()})}else{mau=false;simpan(false);v.muted=true;ui()}});if(mau){nyala().catch(function(){v.muted=true;v.play().catch(function(){});ui();tunggu()})}ui()})();</script></body></html>';
